Given a directed graph with V vertices numbered from 0 to V - 1 and E directed edges. The graph is represented using a 2D array edges[][] of size E, where each entry edges[i] = [u, v] denotes a directed edge from vertex u to vertex v.Check whether the graph contains any cycle. Return true if there exists at least one cycle in the graph; otherwise, return false.Examples: Input:  V = 4, edges[][] = [[0, 1], [1, 2], [2, 0], [2, 3]] Output:  trueExplanation:  The diagram clearly shows a cycle 0 -> 1 -> 2 -> 0Input: V = 4, edges[][] = [[0, 1], [0, 2], [1, 2], [2, 3]] Output: falseExplanation: no cycle in the graphTry It YourselfTable of ContentUsing  DFS - O(V + E) Time and O(V) SpaceUsing  Topological Sorting - O(V + E) Time and O(V) SpaceUsing  DFS - O(V + E) Time and O(V) SpaceTo detect a cycle in a directed graph, we use Depth First Search (DFS). If DFS reaches a vertex that is already present in the current DFS path, a cycle exists.Using only visited[] is not enough. A vertex may have been visited during an earlier DFS traversal but may not be part of the current DFS path. Therefore, we also keep track of the vertices currently being explored.For this, we use two arrays:visited[]: Marks vertices that have been visited at least once.recStack[]: Marks vertices that are currently present in the DFS recursion path.If during DFS we reach a vertex whose recStack[] value is true, a cycle is found. After completely exploring all adjacent vertices of a node, we remove it from the current DFS path by setting recStack[u] = false. This ensures that recStack[] contains only the vertices that belong to the current DFS path.
            C++

    #include <bits/stdc++.h>
using namespace std;

bool dfs(vector<vector<int>>& adj, int u,
         vector<bool>& visited, vector<bool>& recStack) {

    // Node is already in the current DFS path
    if (recStack[u])
        return true;

    // Node is already visited
    if (visited[u])
        return false;

    visited[u] = true;
    recStack[u] = true;

    // Visit all adjacent nodes
    for (int v : adj[u]) {
        if (dfs(adj, v, visited, recStack))
            return true;
    }

    // Remove node from current DFS path
    recStack[u] = false;

    return false;
}

bool isCyclic(int V, vector<vector<int>>& edges) {

    vector<vector<int>> adj(V);

    // Create adjacency list
    for (auto& edge : edges) {
        adj[edge[0]].push_back(edge[1]);
    }

    vector<bool> visited(V, false);
    vector<bool> recStack(V, false);

    // Check all components
    for (int i = 0; i < V; i++) {
        if (!visited[i] && dfs(adj, i, visited, recStack))
            return true;
    }

    return false;
}

int main() {

    int V = 4;

    vector<vector<int>> edges = {
        {0, 1},
        {1, 2},
        {2, 0},
        {2, 3}
    };

    cout << (isCyclic(V, edges) ? "true" : "false") << endl;

    return 0;
}


