        {
            adj.Add(new List<int>());
        }

        // Create adjacency list
        for (int i = 0; i < edges.GetLength(0); i++)
        {
            adj[edges[i, 0]].Add(edges[i, 1]);
        }

        // Array to store in-degree of each vertex
        int[] inDegree = new int[V];

